let file = """{"version":3,"file":"useWorkspaceTierLabel-Bmx1JOzD.js","names":[],"sources":["../../src/platform/workspace/composables/useWorkspaceTierLabel.ts"],"sourcesContent":["import { useI18n } from 'vue-i18n'\n\nimport type { SubscriptionTier } from '@/platform/workspace/api/workspaceApi'\n\nconst tierKeyMap: Record<string, string> = {\n  FREE: 'free',\n  STANDARD: 'standard',\n  CREATOR: 'creator',\n  PRO: 'pro',\n  FOUNDER: 'founder',\n  FOUNDERS_EDITION: 'founder',\n  ENTERPRISE: 'enterprise'\n}\n\ninterface WorkspaceSubscriptionInfo {\n  isSubscribed: boolean\n  subscriptionPlan: string | null\n  subscriptionTier: SubscriptionTier | null\n}\n\nexport function useWorkspaceTierLabel() {\n  const { t } = useI18n()\n\n  function formatTierName(\n    tier: string | null | undefined,\n    isYearly: boolean\n  ): string {\n    if (!tier) return ''\n    // TEAM has no `tiers.*` catalog entry (it isn't a self-serve personal\n    // plan); reuse the existing team-plan copy instead of adding one.\n    if (tier === 'TEAM') return t('subscription.teamPlanName')\n    const key = tierKeyMap[tier]\n    if (!key) return ''\n    const baseName = t(`subscription.tiers.${key}.name`)\n    return isYearly\n      ? t('subscription.tierNameYearly', { name: baseName })\n      : baseName\n  }\n\n  function getTierLabel(workspace: WorkspaceSubscriptionInfo): string | null {\n    if (!workspace.isSubscribed) return null\n\n    if (workspace.subscriptionTier) {\n      return formatTierName(workspace.subscriptionTier, false)\n    }\n\n    if (!workspace.subscriptionPlan) return null\n\n    // Plan identifiers arrive in both cases: comfy-api sends uppercase slugs,\n    // cloud sends lowercase ones (e.g. enterprise plan rows).\n    const planSlug = workspace.subscriptionPlan.toUpperCase()\n    const tierMatch = Object.keys(tierKeyMap)\n      .sort((a, b) => b.length - a.length)\n      .find((tier) => planSlug === tier || planSlug.startsWith(`${tier}_`))\n    if (!tierMatch) return null\n\n    const isYearly = planSlug.includes('YEARLY') || planSlug.includes('ANNUAL')\n    return formatTierName(tierMatch, isYearly)\n  }\n\n  return { formatTierName, getTierLabel }\n}\n"],"mappings":"qFAIA,IAAM,EAAqC,CACzC,KAAM,OACN,SAAU,WACV,QAAS,UACT,IAAK,MACL,QAAS,UACT,iBAAkB,UAClB,WAAY,YACd,EAQA,SAAgB,uBAAwB,CACtC,GAAM,CAAE,KAAM,EAAQ,EAEtB,SAAS,eACP,EACA,EACQ,CACR,GAAI,CAAC,EAAM,MAAO,GAGlB,GAAI,IAAS,OAAQ,OAAO,EAAE,2BAA2B,EACzD,IAAM,EAAM,EAAW,GACvB,GAAI,CAAC,EAAK,MAAO,GACjB,IAAM,EAAW,EAAE,sBAAsB,EAAI,MAAM,EACnD,OAAO,EACH,EAAE,8BAA+B,CAAE,KAAM,CAAS,CAAC,EACnD,CACN,CAEA,SAAS,aAAa,EAAqD,CACzE,GAAI,CAAC,EAAU,aAAc,OAAO,KAEpC,GAAI,EAAU,iBACZ,OAAO,eAAe,EAAU,iBAAkB,EAAK,EAGzD,GAAI,CAAC,EAAU,iBAAkB,OAAO,KAIxC,IAAM,EAAW,EAAU,iBAAiB,YAAY,EAClD,EAAY,OAAO,KAAK,CAAU,CAAC,CACtC,MAAM,EAAG,IAAM,EAAE,OAAS,EAAE,MAAM,CAAC,CACnC,KAAM,GAAS,IAAa,GAAQ,EAAS,WAAW,GAAG,EAAK,EAAE,CAAC,EAItE,OAHK,EAGE,eAAe,EADL,EAAS,SAAS,QAAQ,GAAK,EAAS,SAAS,QAAQ,CACjC,EAHlB,IAIzB,CAEA,MAAO,CAAE,eAAgB,YAAa,CACxC"}"""

